import{_ as l,o as t,c as a,ae as n}from"./chunks/framework.vXWZTEWX.js";const h=JSON.parse('{"title":"ADR 038: Full Stack Vercel Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"adr/038-vercel-fullstack-deployment.md","filePath":"adr/038-vercel-fullstack-deployment.md"}'),r={name:"adr/038-vercel-fullstack-deployment.md"};function o(i,e,c,s,d,u){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-038-full-stack-vercel-deployment" tabindex="-1">ADR 038: Full Stack Vercel Deployment <a class="header-anchor" href="#adr-038-full-stack-vercel-deployment" aria-label="Permalink to &quot;ADR 038: Full Stack Vercel Deployment&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2026-04-15</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The application was initially deployed with frontend on Vercel and backend on Render. This caused:</p><ul><li>Cold start delays on Render backend</li><li>Two separate deployment platforms to manage</li><li>Complexity in orchestration</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Migrate the entire stack (frontend + backend) to Vercel.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><p><strong>Pros:</strong></p><ul><li>Single deployment platform</li><li>Faster cold starts</li><li>Unified domain: <a href="https://tendercheckai.elecodes.online/" target="_blank" rel="noreferrer">https://tendercheckai.elecodes.online/</a></li><li>Simpler CI/CD</li></ul></li><li><p><strong>Cons:</strong></p><ul><li>Need to configure Vercel for API routes (<code>VERCEL_PREPATH</code>)</li><li>May need to adjust build configuration</li></ul></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>ADR 016 (original Render pivot)</li><li>ADR 036 (Vercel frontend)</li></ul>',11)])])}const f=l(r,[["render",o]]);export{h as __pageData,f as default};
